insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'A support team wants to reduce resolution delays. Which metric most directly measures that objective?','Median time from ticket creation to resolution','["Number of dashboard colors","Total number of employees","Number of charts published"]'::jsonb,'Elapsed resolution time measures the delay the team wants to reduce.','{"Median time from ticket creation to resolution":"Elapsed resolution time measures the delay the team wants to reduce.","Number of dashboard colors":"Visual styling does not measure resolution delay.","Total number of employees":"Headcount may influence capacity but is not the delay itself.","Number of charts published":"Chart production measures reporting activity, not support outcomes."}'::jsonb,'application','applied-v1-BCIS-411-1' from public.courses c join public.topics t on t.course_id=c.id and t.name='KPI' where c.code='BCIS 411' on conflict(content_key) where content_key is not null do nothing;
insert into public.topics(course_id,name) select id,'data visualization' from public.courses where code='BCIS 411' on conflict(course_id,name) do nothing;
insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'A dashboard compares sales across five regions. Which chart makes their magnitudes easy to compare?','Bar chart with a common zero baseline','["A separate pie chart for each region","A 3D decorative sphere","A line chart with regions randomly reordered every day"]'::jsonb,'Bars sharing a baseline make category magnitudes straightforward to compare.','{"Bar chart with a common zero baseline":"Bars sharing a baseline make category magnitudes straightforward to compare.","A separate pie chart for each region":"Separate pies lack a common comparable scale.","A 3D decorative sphere":"Decoration does not encode the comparison clearly.","A line chart with regions randomly reordered every day":"Random category order makes comparison unstable and lines imply sequence."}'::jsonb,'application','applied-v1-BCIS-411-2' from public.courses c join public.topics t on t.course_id=c.id and t.name='data visualization' where c.code='BCIS 411' on conflict(content_key) where content_key is not null do nothing;
