insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'Sales revenue is counted twice after joining orders to order lines. What should be checked first?','The grain of each table and whether order totals repeat per line','["The dashboard background color","The number of user passwords","The screen brightness"]'::jsonb,'An order-level total repeated across line-level rows is double-counted when summed.','{"The grain of each table and whether order totals repeat per line":"An order-level total repeated across line-level rows is double-counted when summed.","The dashboard background color":"Appearance does not alter aggregation grain.","The number of user passwords":"Passwords do not explain duplicated revenue rows.","The screen brightness":"Screen settings do not change the data calculation."}'::jsonb,'debugging','applied-v1-BCIS-411-3' from public.courses c join public.topics t on t.course_id=c.id and t.name='data warehouse' where c.code='BCIS 411' on conflict(content_key) where content_key is not null do nothing;
