insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'A source changes date formatting from DD/MM/YYYY to MM/DD/YYYY. What should a pipeline do?','Validate and explicitly parse the expected source date format','["Treat every date as plain text forever","Silently guess each date format","Drop all dates without reporting it"]'::jsonb,'Explicit parsing and validation prevent ambiguous dates from being silently misinterpreted.','{"Validate and explicitly parse the expected source date format":"Explicit parsing and validation prevent ambiguous dates from being silently misinterpreted.","Treat every date as plain text forever":"Plain text prevents reliable date operations and leaves ambiguity unresolved.","Silently guess each date format":"Guessing can swap month and day without detection.","Drop all dates without reporting it":"Silent removal loses information and hides the issue."}'::jsonb,'application','applied-v1-BCIS-411-4' from public.courses c join public.topics t on t.course_id=c.id and t.name='ETL' where c.code='BCIS 411' on conflict(content_key) where content_key is not null do nothing;
insert into public.topics(course_id,name) select id,'dashboard' from public.courses where code='BCIS 411' on conflict(course_id,name) do nothing;
insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'A KPI reports 120% of target. Actual sales are 600. What was the target?','500','["720","120","600"]'::jsonb,'Actual ÷ target = 1.2, so target = 600 ÷ 1.2 = 500.','{"120":"120 is the percentage number, not the monetary target.","500":"Actual ÷ target = 1.2, so target = 600 ÷ 1.2 = 500.","600":"A target of 600 would yield 100%.","720":"720 multiplies actual by 1.2 instead of solving for the target."}'::jsonb,'application','applied-v1-BCIS-411-5' from public.courses c join public.topics t on t.course_id=c.id and t.name='dashboard' where c.code='BCIS 411' on conflict(content_key) where content_key is not null do nothing;
insert into public.topics(course_id,name) select id,'data quality' from public.courses where code='BCIS 411' on conflict(course_id,name) do nothing;
insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'Two reports show different monthly totals because one includes cancelled orders. What should be agreed first?','A shared business definition of included revenue transactions','["Which report has the nicer layout","A random adjustment to make totals equal","A policy to stop comparing reports"]'::jsonb,'Consistent inclusion rules are needed before two totals can be meaningfully compared.','{"A shared business definition of included revenue transactions":"Consistent inclusion rules are needed before two totals can be meaningfully compared.","Which report has the nicer layout":"Layout does not resolve different business definitions.","A random adjustment to make totals equal":"An arbitrary adjustment conceals the reason for the difference.","A policy to stop comparing reports":"Avoiding comparison leaves the inconsistency unresolved."}'::jsonb,'application','applied-v1-BCIS-411-6' from public.courses c join public.topics t on t.course_id=c.id and t.name='data quality' where c.code='BCIS 411' on conflict(content_key) where content_key is not null do nothing;
insert into public.topics(course_id,name) select id,'mean' from public.courses where code='BCIS 421' on conflict(course_id,name) do nothing;
insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'Sales values are 10, 10, 10 and 90. What is their mean?','30','["10","90","120"]'::jsonb,'The total is 120; divide by four observations to obtain 30.','{"10":"10 is the median and mode here, not the mean.","30":"The total is 120; divide by four observations to obtain 30.","90":"90 is the maximum. It does not answer the requested calculation.","120":"120 is the sum before division."}'::jsonb,'application','applied-v1-BCIS-421-1' from public.courses c join public.topics t on t.course_id=c.id and t.name='mean' where c.code='BCIS 421' on conflict(content_key) where content_key is not null do nothing;
insert into public.topics(course_id,name) select id,'median' from public.courses where code='BCIS 421' on conflict(course_id,name) do nothing;
insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'For delivery times 2, 3, 3, 4 and 100 days, which summary is less distorted by the extreme delay?','Median: 3 days','["Mean: 22.4 days","Maximum: 100 days","Sum: 112 days"]'::jsonb,'The median is the middle ordered value and is less sensitive to one extreme value.','{"Median: 3 days":"The median is the middle ordered value and is less sensitive to one extreme value.","Mean: 22.4 days":"The extreme delay pulls the mean well above most observations.","Maximum: 100 days":"The maximum describes only the most extreme case.","Sum: 112 days":"The sum is not a typical per-delivery duration."}'::jsonb,'application','applied-v1-BCIS-421-2' from public.courses c join public.topics t on t.course_id=c.id and t.name='median' where c.code='BCIS 421' on conflict(content_key) where content_key is not null do nothing;
insert into public.topics(course_id,name) select id,'test set' from public.courses where code='BCIS 421' on conflict(course_id,name) do nothing;
insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'A model''s settings were repeatedly chosen based on test-set scores. What is the problem?','The test set influenced development and no longer provides an untouched final evaluation','["Test data must always train the model","More test-set tuning guarantees generalization","A high test score proves causation"]'::jsonb,'Repeated tuning against the test set leaks evaluation information into development.','{"The test set influenced development and no longer provides an untouched final evaluation":"Repeated tuning against the test set leaks evaluation information into development.","Test data must always train the model":"Training on test data defeats its independent evaluation role.","More test-set tuning guarantees generalization":"Repeated tuning can overfit the test set.","A high test score proves causation":"Predictive performance does not establish a causal relationship."}'::jsonb,'application','applied-v1-BCIS-421-3' from public.courses c join public.topics t on t.course_id=c.id and t.name='test set' where c.code='BCIS 421' on conflict(content_key) where content_key is not null do nothing;
insert into public.topics(course_id,name) select id,'classification' from public.courses where code='BCIS 421' on conflict(course_id,name) do nothing;
insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'Only 1% of transactions are fraud. A model predicts every transaction as non-fraud. Which statement is correct?','It has 99% accuracy but detects none of the fraud cases','["It detects 99% of fraud","Its accuracy is 1%","It has perfect fraud recall"]'::jsonb,'The majority class creates high accuracy, while fraud recall is zero.','{"It has 99% accuracy but detects none of the fraud cases":"The majority class creates high accuracy, while fraud recall is zero.","It detects 99% of fraud":"Overall accuracy is not the same as fraud detection rate.","Its accuracy is 1%":"It correctly predicts the 99% non-fraud majority.","It has perfect fraud recall":"It misses every fraud case, so recall is zero."}'::jsonb,'application','applied-v1-BCIS-421-4' from public.courses c join public.topics t on t.course_id=c.id and t.name='classification' where c.code='BCIS 421' on conflict(content_key) where content_key is not null do nothing;
insert into public.topics(course_id,name) select id,'overfitting' from public.courses where code='BCIS 421' on conflict(course_id,name) do nothing;
insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'A model achieves 99% training accuracy and 62% validation accuracy. What is a reasonable concern?','It may be overfitting the training data','["It must generalize perfectly","Validation accuracy should be ignored","The validation labels should be replaced with model predictions"]'::jsonb,'A large training-validation gap suggests the model may have learned training-specific patterns.','{"It may be overfitting the training data":"A large training-validation gap suggests the model may have learned training-specific patterns.","It must generalize perfectly":"The validation result contradicts perfect generalization.","Validation accuracy should be ignored":"Validation performance helps assess unseen-data behavior.","The validation labels should be replaced with model predictions":"Replacing labels would invalidate evaluation."}'::jsonb,'application','applied-v1-BCIS-421-5' from public.courses c join public.topics t on t.course_id=c.id and t.name='overfitting' where c.code='BCIS 421' on conflict(content_key) where content_key is not null do nothing;
insert into public.topics(course_id,name) select id,'missing values' from public.courses where code='BCIS 421' on conflict(course_id,name) do nothing;
insert into public.questions(course_id,topic_id,question,correct_answer,wrong_answers,explanation,option_explanations,question_kind,content_key) select c.id,t.id,'Income is missing for 20% of rows. Why is replacing every missing value with zero risky?','Zero income is a real value and can bias the analysis if missingness means unknown','["Zero is always the correct imputation","Missing values are necessarily fraudulent","Replacing values cannot affect a mean"]'::jsonb,'Choose a justified missing-data strategy; unknown income is not automatically zero income.','{"Zero income is a real value and can bias the analysis if missingness means unknown":"Choose a justified missing-data strategy; unknown income is not automatically zero income.","Zero is always the correct imputation":"The appropriate strategy depends on context and the missingness mechanism.","Missing values are necessarily fraudulent":"Missingness alone does not establish fraud.","Replacing values cannot affect a mean":"Adding zeros changes both summaries and model inputs."}'::jsonb,'application','applied-v1-BCIS-421-6' from public.courses c join public.topics t on t.course_id=c.id and t.name='missing values' where c.code='BCIS 421' on conflict(content_key) where content_key is not null do nothing;

